#[test]
fn rust_backend_uses_compact_general_ad_store_helpers() {
    let artifact = VerilogACompiler::default()
        .compile_canonical_ir(compact_general_ad_store_source())
        .expect("canonical IR");
    let generated = RustTranspiler::new(RustTranspileOptions {
        runtime_path: "crate::runtime".to_string(),
    })
    .transpile(&artifact)
    .expect("transpile compact general AD stores");
    let stamp = generated
        .files
        .iter()
        .find(|file| file.relative_path == "stamp.rs")
        .expect("stamp file")
        .contents
        .as_str();
    let support = render_runtime_support_module();

    assert!(support.contains("pub(crate) fn store_mul_ad("), "{support}");
    assert!(
        support.contains("pub(crate) fn store_sqrt_ad("),
        "{support}"
    );
    assert!(
        stamp.contains("s.store_mul_ad(2, A::add(s.ad_value(0), s.ad_value(1)), A::sub(s.ad_value(0), s.ad_value(1)));"),
        "{stamp}"
    );
    assert!(
        stamp.contains("s.store_add_ad(3, A::add(s.ad_value(0), s.ad_value(1)), A::sub(s.ad_value(0), s.ad_value(1)));"),
        "{stamp}"
    );
    assert!(
        stamp.contains("s.store_sub_ad(4, A::add(s.ad_value(0), s.ad_value(1)), A::sub(s.ad_value(0), s.ad_value(1)));"),
        "{stamp}"
    );
    assert!(
        stamp.contains("s.store_div_ad(5, A::add(s.ad_value(0), s.ad_value(1)), A::sub(s.ad_value(0), s.ad_value(1)));"),
        "{stamp}"
    );
    assert!(stamp.contains("s.store_sqrt_add(6, 0, 1);"), "{stamp}");
    assert!(stamp.contains("s.store_exp_add(7, 0, 1);"), "{stamp}");
    assert!(
        stamp.contains("s.store_scaled_sqrt_ad(8, A::add(s.ad_value(0), s.ad_value(1)), p.p0);"),
        "{stamp}"
    );
    assert!(
        stamp.contains("s.store_offset_sqrt_ad(9, A::add(s.ad_value(0), s.ad_value(1)), p.p1);"),
        "{stamp}"
    );
    assert!(
        stamp.contains(
            "s.store_sub_from_scalar_ad(10, p.p0, A::sqrt(A::add(s.ad_value(0), s.ad_value(1))));"
        ),
        "{stamp}"
    );
    assert!(
        stamp.contains(
            "s.store_div_from_scalar_sqrt_ad(11, p.p0, A::add(s.ad_value(0), s.ad_value(1)));"
        ),
        "{stamp}"
    );
    assert!(
        stamp.contains("s.store_powf_ad(12, A::sqrt(A::add(s.ad_value(0), s.ad_value(1))), p.p0);"),
        "{stamp}"
    );
    assert!(
        stamp.contains("s.store_neg_ad(13, A::sqrt(A::add(s.ad_value(0), s.ad_value(1))));"),
        "{stamp}"
    );
    assert_generated_rust_compiles(&generated);
}

