#[test]
fn rust_backend_omits_reactive_work_for_models_without_ddt() {
    let artifact = VerilogACompiler::default()
        .compile_canonical_ir(assignment_fed_resistor_source())
        .expect("canonical IR");
    let generated = RustTranspiler::default()
        .transpile(&artifact)
        .expect("transpile assignment-fed resistor");
    let stamp = generated
        .files
        .iter()
        .find(|file| file.relative_path == "stamp.rs")
        .expect("stamp file")
        .contents
        .as_str();
    let reactive_body = stamp
        .split("pub fn stamp_reactive")
        .nth(1)
        .expect("reactive method");

    assert!(!reactive_body.contains("let mut g"), "{reactive_body}");
    assert!(!reactive_body.contains("g = "), "{reactive_body}");
    assert!(!reactive_body.contains("_q"), "{reactive_body}");
    assert!(
        !reactive_body.contains("let p ="),
        "empty reactive stamps should not bind params:\n{reactive_body}"
    );
    assert!(
        !reactive_body.contains("let nodes ="),
        "empty reactive stamps should not bind nodes:\n{reactive_body}"
    );
    assert!(
        !reactive_body.contains("let branches ="),
        "empty reactive stamps should not bind branches:\n{reactive_body}"
    );
    assert!(
        !reactive_body.contains("let timestep ="),
        "empty reactive stamps should not bind timestep:\n{reactive_body}"
    );
    assert!(
        !reactive_body.contains("stamp_current_reactive"),
        "{reactive_body}"
    );
}

#[test]
fn rust_backend_lowers_scalar_assignments_before_current_equations() {
    let src = r#"
module assigned_res(p, n);
    inout p, n;
    electrical p, n;
    parameter real r = 1000.0 from (0:inf);
    real g;
    analog begin
        g = 1.0 / r;
        I(p, n) <+ g * V(p, n);
    end
endmodule
"#;
    let artifact = VerilogACompiler::default()
        .compile_canonical_ir(src)
        .expect("canonical IR");

    let generated = RustTranspiler::default()
        .transpile(&artifact)
        .expect("transpile assignment-fed resistor");
    let stamp = generated
        .files
        .iter()
        .find(|file| file.relative_path == "stamp.rs")
        .expect("stamp file")
        .contents
        .as_str();

    assert!(
        stamp.contains("let s = match &mut self.scratch {"),
        "{stamp}"
    );
    assert!(!stamp.contains("Scratch::new();"), "{stamp}");
    assert!(stamp.contains("s.v[0] = (1.0 / p.p0);"), "{stamp}");
    assert!(!stamp.contains("s.store_ad(0"), "{stamp}");
    assert!(stamp.contains("eq0_value"), "{stamp}");
    assert!(!stamp.contains("s.dn[0]"), "{stamp}");
    assert!(!stamp.contains("g_d_n0 ="), "{stamp}");
    assert!(!stamp.contains("g_d_n1 ="), "{stamp}");
    assert!(!stamp.contains("0.0 *"), "{stamp}");
    assert!(!stamp.contains("* 0.0"), "{stamp}");
    assert!(!stamp.contains(": f64 = g;"), "{stamp}");
    assert!(!stamp.contains("HashMap"), "{stamp}");
    assert!(!stamp.contains("Bytecode"), "{stamp}");
    assert!(!stamp.contains("g_q"), "{stamp}");
}

