#[test]
fn rust_backend_splits_transient_and_reactive_scratch_storage() {
    let artifact = VerilogACompiler::default()
        .compile_canonical_ir(mixed_dynamic_static_source())
        .expect("canonical IR");
    let generated = RustTranspiler::default()
        .transpile(&artifact)
        .expect("transpile mixed dynamic/static device");
    let stamp = generated
        .files
        .iter()
        .find(|file| file.relative_path == "stamp.rs")
        .expect("stamp file")
        .contents
        .as_str();
    let support = render_runtime_support_module();
    let transient_scratch = support
        .split("pub(crate) struct Scratch")
        .nth(1)
        .expect("transient scratch struct")
        .split("pub(crate) struct ReactiveScratch")
        .next()
        .expect("transient scratch section");
    let reactive_scratch = support
        .split("pub(crate) struct ReactiveScratch")
        .nth(1)
        .expect("reactive scratch struct")
        .split("pub(crate) struct AdValue")
        .next()
        .expect("reactive scratch section");

    assert!(!transient_scratch.contains("pub(crate) rv:"), "{stamp}");
    assert!(!transient_scratch.contains("pub(crate) rdn:"), "{stamp}");
    assert!(reactive_scratch.contains("pub(crate) rv:"), "{stamp}");
    assert!(
        stamp.contains("let s = match &mut self.scratch {"),
        "{stamp}"
    );
    assert!(
        stamp.contains("let s = match &mut self.reactive_scratch {"),
        "{stamp}"
    );
    assert!(!stamp.contains("Scratch::new();"), "{stamp}");
    assert!(!stamp.contains("ReactiveScratch::new();"), "{stamp}");
    assert!(stamp.contains("type Scratch = GenericScratch"), "{stamp}");
    assert!(
        stamp.contains("type ReactiveScratch = GenericReactiveScratch"),
        "{stamp}"
    );
}

