#[test]
fn rust_backend_uses_compact_parameter_state_initialization_and_validation() {
    let artifact = VerilogACompiler::default()
        .compile_canonical_ir(compact_parameter_state_source())
        .expect("canonical IR");
    let generated = RustTranspiler::default()
        .transpile(&artifact)
        .expect("transpile compact parameter-state device");
    let state = generated
        .files
        .iter()
        .find(|file| file.relative_path == "state.rs")
        .expect("state file")
        .contents
        .as_str();

    assert!(
        state.contains("std::ptr::write_bytes(ptr, 0, 1);"),
        "parameter defaults should zero the heap allocation without emitting an all-field initializer:\n{state}"
    );
    assert!(
        state.starts_with("#![allow(dead_code, unused_parens, unused_variables)]"),
        "generated state files should suppress warning storms from mechanical expressions:\n{state}"
    );
    assert!(
        state.contains("fn validate_parameter("),
        "parameter validation should use one shared generated helper:\n{state}"
    );
    assert!(
        state.contains("fn validate_finite_parameter("),
        "unconstrained parameter validation should use a compact finite-only helper:\n{state}"
    );
    assert!(
        !state.contains("validate_parameter(\"r\", params.p0"),
        "constant defaults are already validated during codegen and should not emit default-time checks:\n{state}"
    );
    assert!(
        !state.contains("validate_parameter(\"scale\", params.p1"),
        "constant defaults with ranges are already validated during codegen and should not emit default-time checks:\n{state}"
    );
    assert!(
        state.contains("validate_finite_parameter(\"derived\", params.p2"),
        "unconstrained dependent defaults should keep runtime finite validation:\n{state}"
    );
    assert!(
        !state
            .contains("validate_parameter(\"derived\", params.p2, None, false, None, false, &[])"),
        "unconstrained defaults should not emit the full range validator call:\n{state}"
    );
    assert!(
        state.contains("validate_finite_parameter(\"derived\", value)?"),
        "unconstrained set_parameter values should keep finite validation through the compact helper:\n{state}"
    );
    assert!(
        !state.contains("fn validate_parameter_r("),
        "parameter validation should not emit one function per parameter:\n{state}"
    );
    assert!(
        !state.contains("r: 0.0,"),
        "parameter defaults should not emit a zero initializer per field:\n{state}"
    );
}

#[test]
fn rust_backend_uses_compact_parameter_field_names_in_generated_rust() {
    let artifact = VerilogACompiler::default()
        .compile_canonical_ir(compact_parameter_field_source())
        .expect("canonical IR");
    let generated = RustTranspiler::default()
        .transpile(&artifact)
        .expect("transpile compact parameter-field device");
    let state = generated
        .files
        .iter()
        .find(|file| file.relative_path == "state.rs")
        .expect("state file")
        .contents
        .as_str();
    let stamp = generated
        .files
        .iter()
        .find(|file| file.relative_path == "stamp.rs")
        .expect("stamp file")
        .contents
        .as_str();

    assert!(state.contains("pub p0: f64"), "{state}");
    assert!(state.contains("pub p1: f64"), "{state}");
    assert!(
        stamp.contains("let p = Box::as_ref(&self.params);"),
        "{stamp}"
    );
    assert!(!stamp.contains("let p = self.params;"), "{stamp}");
    assert!(!stamp.contains("let p = self.p.as_ref();"), "{stamp}");
    assert!(stamp.contains("let nodes = &(*self).nodes;"), "{stamp}");
    assert!(!stamp.contains("let nodes = self.nodes;"), "{stamp}");
    assert!(stamp.contains("p.p0"), "{stamp}");
    assert!(stamp.contains("p.p1"), "{stamp}");
    assert!(
        stamp.contains("let nv0 = ctx.node_voltage(nodes[0]);"),
        "{stamp}"
    );
    assert!(
        stamp.contains("let nv1 = ctx.node_voltage(nodes[1]);"),
        "{stamp}"
    );
    assert!(stamp.contains("nv0 - nv1"), "{stamp}");
    assert!(!stamp.contains("params.p0"), "{stamp}");
    assert!(!stamp.contains("params.p1"), "{stamp}");
    assert!(!stamp.contains("self.params.p0"), "{stamp}");
    assert!(!stamp.contains("self.params.p1"), "{stamp}");
    assert!(
        !state.contains("pub very_long_process_corner_gain_parameter"),
        "generated Rust field names should be compact while preserving public parameter lookup names:\n{state}"
    );
    assert!(
        !stamp.contains("params.very_long_process_corner_gain_parameter"),
        "stamp code should not repeat long public parameter names:\n{stamp}"
    );
}

#[test]
fn rust_backend_uses_compact_clone_state_without_debug_derives() {
    let artifact = VerilogACompiler::default()
        .compile_canonical_ir(compact_parameter_state_source())
        .expect("canonical IR");
    let generated = RustTranspiler::default()
        .transpile(&artifact)
        .expect("transpile compact parameter-state device");
    let state = generated
        .files
        .iter()
        .find(|file| file.relative_path == "state.rs")
        .expect("state file")
        .contents
        .as_str();

    assert!(state.contains("impl Copy for Parameters {}"), "{state}");
    assert!(
        state.contains("fn clone(&self) -> Self { *self }"),
        "{state}"
    );
    assert!(!state.contains("impl Copy for Instance {}"), "{state}");
    assert!(state.contains("pub params: Box<Parameters>"), "{state}");
    assert!(
        state.contains("pub(crate) param_given: Box<[bool; 3]>"),
        "{state}"
    );
    assert!(
        state.contains("pub(crate) ddt_state_current: Box<[f64; 0]>"),
        "{state}"
    );
    assert!(
        state.contains("pub(crate) scratch: Option<Box<GenericScratch<"),
        "{state}"
    );
    assert!(
        state.contains("pub(crate) reactive_scratch: Option<Box<GenericReactiveScratch<"),
        "{state}"
    );
    assert!(state.contains("params: Parameters::new_box()"), "{state}");
    assert!(
        state.contains("fn boxed_zero_f64_array<const N: usize>() -> Box<[f64; N]>"),
        "{state}"
    );
    assert!(
        state.contains("fn boxed_zero_bool_array<const N: usize>() -> Box<[bool; N]>"),
        "{state}"
    );
    assert!(
        state.contains("param_given: boxed_zero_bool_array::<{ Self::PARAMETER_COUNT }>()"),
        "{state}"
    );
    assert!(
        state.contains("ddt_state_current: boxed_zero_f64_array::<{ Self::DDT_STATE_COUNT }>()"),
        "{state}"
    );
    assert!(
        state.contains("scratch: Some(GenericScratch::new_box())"),
        "{state}"
    );
    assert!(
        state.contains("reactive_scratch: Some(GenericReactiveScratch::new_box())"),
        "{state}"
    );
    assert!(state.contains("params: self.params.clone()"), "{state}");
    assert!(state.contains("scratch: None"), "{state}");
    assert!(state.contains("reactive_scratch: None"), "{state}");
    assert!(
        !state.contains("#[derive(Debug, Clone)]"),
        "large generated state should not synthesize Debug or field-by-field Clone impls:\n{state}"
    );
}

#[test]
fn rust_backend_generates_restore_that_preserves_live_scratch_buffers() {
    let artifact = VerilogACompiler::default()
        .compile_canonical_ir(compact_parameter_state_source())
        .expect("canonical IR");
    let generated = RustTranspiler::default()
        .transpile(&artifact)
        .expect("transpile compact parameter-state device");
    let state = generated
        .files
        .iter()
        .find(|file| file.relative_path == "state.rs")
        .expect("state file")
        .contents
        .as_str();

    assert!(
        state.contains("pub fn restore_from_snapshot(&mut self, snapshot: Self)"),
        "{state}"
    );
    assert!(
        state.contains("let scratch = self.scratch.take();"),
        "{state}"
    );
    assert!(
        state.contains("let reactive_scratch = self.reactive_scratch.take();"),
        "{state}"
    );
    assert!(
        state.contains("scratch,"),
        "restore must preserve the active transient scratch allocation:\n{state}"
    );
    assert!(
        state.contains("reactive_scratch,"),
        "restore must preserve the active reactive scratch allocation:\n{state}"
    );
    assert!(
        !state.contains("scratch: snapshot.scratch"),
        "restore must not import snapshot scratch, which clones intentionally strip:\n{state}"
    );
    assert!(
        !state.contains("reactive_scratch: snapshot.reactive_scratch"),
        "restore must not import snapshot reactive scratch, which clones intentionally strip:\n{state}"
    );
}

#[test]
fn generated_compact_parameter_state_rust_compiles_with_runtime_stub() {
    let artifact = VerilogACompiler::default()
        .compile_canonical_ir(compact_parameter_state_source())
        .expect("canonical IR");
    let generated = RustTranspiler::new(RustTranspileOptions {
        runtime_path: "crate::runtime".to_string(),
    })
    .transpile(&artifact)
    .expect("transpile compact parameter-state device");

    assert_generated_rust_compiles(&generated);
}

