#[test]
fn rust_backend_propagates_branch_current_axis_through_assignment() {
    let artifact = VerilogACompiler::default()
        .compile_canonical_ir(assigned_branch_current_axis_source())
        .expect("canonical IR");
    let generated = RustTranspiler::default()
        .transpile(&artifact)
        .expect("transpile assigned branch-current axis device");
    let stamp = generated
        .files
        .iter()
        .find(|file| file.relative_path == "stamp.rs")
        .expect("stamp file")
        .contents
        .as_str();

    assert!(
        stamp.contains("stamper.stamp_potential_node2_branch1_local("),
        "{stamp}"
    );
    assert!(
        !stamp.contains("GeneratedDerivative::branch(branches[0]"),
        "{stamp}"
    );
    assert!(stamp.contains("A::branch_current"), "{stamp}");
    assert!(stamp.contains("p.p0"), "{stamp}");
}

#[test]
