fn repeated_conditional_assignment_source() -> &'static str {
    r#"
module repeated_conditional_assignment(p, n);
    inout p, n;
    electrical p, n;
    parameter real gate = 1.0;
    real a;
    real b;
    real c;
    real d;
    analog begin
        a = V(p, n);
        if (gate > 0.0) begin
            b = a + 1.0;
            c = b + 2.0;
            d = c + 3.0;
        end else begin
            b = a - 1.0;
            c = b - 2.0;
            d = c - 3.0;
        end
        I(p, n) <+ d;
    end
endmodule
"#
}

