fn compact_ad_operation_store_source() -> &'static str {
    r#"
module compact_ad_operation_store(p, n);
    inout p, n;
    electrical p, n;
    parameter real gain = 2.0;
    parameter real offset = 1.0;
    real a;
    real b;
    real c;
    real d;
    real e;
    real f;
    real g;
    real h;
    real i;
    real j;
    real k;
    real l;
    analog begin
        a = V(p, n);
        b = V(n, p);
        c = a * b;
        d = c + a;
        e = d - b;
        f = e / a;
        g = sqrt(f);
        h = pow(g, 2.0);
        i = h * gain;
        j = i + offset;
        k = gain - j;
        l = -k;
        I(p, n) <+ l;
    end
endmodule
"#
}

fn compact_nested_ad_operation_store_source() -> &'static str {
    r#"
module compact_nested_ad_operation_store(p, n);
    inout p, n;
    electrical p, n;
    parameter real gain = 2.0;
    parameter real offset = 1.0;
    real a;
    real b;
    real c;
    real d;
    real e;
    real f;
    real g;
    real h;
    real i;
    real j;
    real k;
    analog begin
        a = V(p, n);
        b = V(n, p);
        c = (a + b) * gain;
        d = (a - b) * gain;
        e = (a * b) * gain;
        f = (a / b) * gain;
        g = (a * gain) + offset;
        h = (a + offset) * gain;
        i = (a + offset) + gain;
        j = exp(a) * gain;
        k = sqrt(a) * gain;
        I(p, n) <+ c + d + e + f + g + h + i + j + k;
    end
endmodule
"#
}

