fn compact_expression_scaled_input_intrinsics_source() -> &'static str {
    r#"
module compact_expression_scaled_input_intrinsics(p, n);
    inout p, n;
    electrical p, n;
    parameter real gain = 2.0;
    analog function real lexp;
        input x;
        real x;
        begin
            if (x > 80.0) begin
                lexp = 5.540622384e34 * (1.0 + x - 80.0);
            end else if (x < -80.0) begin
                lexp = 1.804851387e-35;
            end else begin
                lexp = exp(x);
            end
        end
    endfunction
    real a;
    real y;
    analog begin
        a = V(p, n) + 3.0;
        y = exp(a * gain)
            + limexp(a * gain)
            + lexp(a * gain)
            + ln(a * gain)
            + sqrt(a * gain)
            + tanh(a * gain)
            + abs(a * gain);
        I(p, n) <+ y * V(p, n);
    end
endmodule
"#
}

fn compact_output_scaled_and_offset_unary_store_source() -> &'static str {
    r#"
module compact_output_scaled_and_offset_unary_store(p, n);
    inout p, n;
    electrical p, n;
    parameter real gain = 2.0;
    parameter real offset = 3.0;
    analog function real lexp;
        input x;
        real x;
        begin
            if (x > 80.0) begin
                lexp = 5.540622384e34 * (1.0 + x - 80.0);
            end else if (x < -80.0) begin
                lexp = 1.804851387e-35;
            end else begin
                lexp = exp(x);
            end
        end
    endfunction
    real a;
    real b;
    real c;
    real d;
    real e;
    real f;
    real g;
    real h;
    real i;
    real j;
    real k;
    real l;
    analog begin
        a = V(p, n);
        b = (a * a) * gain;
        c = abs(a) * gain;
        d = ln(a) * gain;
        e = lexp(a) * gain;
        f = (a * a) + offset;
        g = abs(a) + offset;
        h = sqrt(a) + offset;
        i = exp(a) + offset;
        j = ln(a) + offset;
        k = limexp(a) + offset;
        l = lexp(a) + offset;
        I(p, n) <+ b + c + d + e + f + g + h + i + j + k + l;
    end
endmodule
"#
}

