fn compact_general_ad_store_source() -> &'static str {
    r#"
module compact_general_ad_store(p, n);
    inout p, n;
    electrical p, n;
    parameter real gain = 2.0;
    parameter real offset = 1.0;
    real a;
    real b;
    real c;
    real d;
    real e;
    real f;
    real g;
    real h;
    real i;
    real j;
    real k;
    real l;
    real m;
    real o;
    analog begin
        a = V(p, n);
        b = V(n, p);
        c = (a + b) * (a - b);
        d = (a + b) + (a - b);
        e = (a + b) - (a - b);
        f = (a + b) / (a - b);
        g = sqrt(a + b);
        h = exp(a + b);
        i = sqrt(a + b) * gain;
        j = sqrt(a + b) + offset;
        k = gain - sqrt(a + b);
        l = gain / sqrt(a + b);
        m = pow(sqrt(a + b), gain);
        o = -sqrt(a + b);
        I(p, n) <+ c + d + e + f + g + h + i + j + k + l + m + o;
    end
endmodule
"#
}

