fn loop_accumulator_source() -> &'static str {
    r#"
module loop_accum(p, n);
    inout p, n;
    electrical p, n;
    real loop;
    real acc;
    analog begin
        loop = 0.0;
        acc = 0.0;
        while (loop < 3.0) begin
            acc = acc + V(p, n);
            loop = loop + 1.0;
        end
        I(p, n) <+ acc;
    end
endmodule
"#
}

